import traceback
import threading


def with_threading_lock(func):
    """
    A decorator that locks a function so that only one thread can execute it at a time.
    """
    lock = threading.Lock()

    def wrapper(*args, **kwargs):
        with lock:
            return func(*args, **kwargs)
    return wrapper


class ThreadWithReturnValue(threading.Thread):
    def __init__(self, group=None, target=None, name=None, args=(), kwargs=None):
        super(ThreadWithReturnValue, self).__init__(group, target, name, args, kwargs)
        self._return = None
        self._exception = None

    @property
    def exception(self):
        return self._exception

    @property
    def formatted_traceback(self):
        return ''.join(traceback.format_exception(type(self._exception), self._exception, self.traceback))

    @property
    def traceback(self):
        return self._exception.__traceback__

    @property
    def return_value(self):
        return self._return

    def run(self):
        try:
            if self._target:
                self._return = self._target(*self._args, **self._kwargs)
        except Exception as e:
            self._exception = e
        finally:
            # Avoid a refcycle if the thread is running a function with
            # an argument that has a member that points to the thread.
            del self._target, self._args, self._kwargs

    def join(self, timeout=None, raise_exception=True):
        """
        Joins the thread and returns the return value of the target function.
        If raise_exception is True, raises the exception that occurred in the thread, if any.
        :param timeout: Timeout for joining the thread.
        :param raise_exception: Whether to raise the exception that occurred in the thread.
        """
        super(ThreadWithReturnValue, self).join(timeout=timeout)
        if raise_exception and self._exception:
            raise self._exception
        return self._return
